package com.amwolfstein.sistrum.library.playlist

/**
 * Fractional indexing for playlist order.
 *
 * Ranks compare as strings over `0-9A-Za-z`; inserting between two ranks writes one row instead of
 * rewriting the list. Ranks are generated by halving the alphabet range.
 */
object LexoRank {
    private const val ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

    fun between(previous: String?, next: String?): String {
        if (previous.isNullOrEmpty() && next.isNullOrEmpty()) return "U"
        if (previous.isNullOrEmpty()) return before(next!!)
        if (next.isNullOrEmpty()) return after(previous)
        require(previous < next) { "previous rank must sort before next rank" }
        var index = 0
        while (index < previous.length && index < next.length && previous[index] == next[index]) {
            index += 1
        }
        val prefix = previous.substring(0, index)
        val low = if (index < previous.length) ALPHABET.indexOf(previous[index]) else 0
        val high = if (index < next.length) ALPHABET.indexOf(next[index]) else ALPHABET.length
        return if (high - low > 1) {
            prefix + ALPHABET[(low + high) / 2]
        } else {
            // Adjacent characters: appending keeps the value after previous and before next.
            previous + ALPHABET[ALPHABET.length / 2]
        }
    }

    fun before(value: String): String {
        if (value.isEmpty()) return "U"
        val first = ALPHABET.indexOf(value.first())
        return when {
            first > 0 -> ALPHABET[first / 2].toString()
            value.length > 1 -> value.dropLast(1)
            else -> "0$value"
        }
    }

    fun after(value: String): String {
        if (value.isEmpty()) return "U"
        val last = ALPHABET.indexOf(value.last())
        return if (last < ALPHABET.length - 1) {
            value.dropLast(1) + ALPHABET[(last + ALPHABET.length) / 2]
        } else {
            value + ALPHABET[ALPHABET.length / 2]
        }
    }
}
